// Frozen seed412 table. No runtime generation or random state.
const encoded='';
const raw=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));const view=new DataView(raw.buffer);const table=new Float32Array(raw.length/4);for(let i=0;i<table.length;i++)table[i]=view.getFloat32(i*4,true);
export function finalAnchor(x,y){const col=Math.floor(x),row=Math.floor(y),i=(col+1+(row+1)*98)*2;let dx=table[i],dy=table[i+1];if(col===0)dx=Math.max(.125,dx);if(col===95)dx=Math.min(-.125,dx);if(row===170)dy=Math.min(-.125,dy);if(!Number.isFinite(dx)||!Number.isFinite(dy))throw Error('anchor bounds');return[dx,dy];}
